      SUBROUTINE DECFIT(INAME,INAMS)      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ICODE.CIN'      INCLUDE 'KNAME.CIN'      INCLUDE 'LNAME.CIN'      INCLUDE 'PARDAT.CIN'      INCLUDE 'PARVAL.CIN'      INCLUDE 'RDWRDS.CIN'C      IPARM = 0      CALL FNDNAM(KNAME,LNAME,INAME)      IF (INAME .NE. 0) THEN        PDATA(INAMS) = FLOAT(ICODE)        IPTYP(INAMS) = 1        PDATA(INAMS+1) = FLOAT(JCODE)        IPTYP(INAMS+1) = 1        INAMS = INAMS + 2        IPARM = 3      ENDIFC  100 RETURN      END